/**
 * Which lap a direction's deltas are measured against. The stored curves are
 * measured against `Record` or `AthleteSet`; the others are references a
 * chart re-bases onto.
 */
export enum FfiReferenceSource {
  /**
   * The direction's record over the whole included history.
   */
  Record,
  /**
   * The activity the athlete set as the section's reference.
   */
  AthleteSet,
  /**
   * The lap that held the direction's record before the current one.
   */
  PreviousRecord,
  /**
   * The point-by-point median of the laps other than the record.
   */
  Typical,
}

const FfiConverterTypeFfiReferenceSource = (() => {
  type TypeName = FfiReferenceSource;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return FfiReferenceSource.Record;
        case 2:
          return FfiReferenceSource.AthleteSet;
        case 3:
          return FfiReferenceSource.PreviousRecord;
        case 4:
          return FfiReferenceSource.Typical;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case FfiReferenceSource.Record:
          return c.writeI32(1);
        case FfiReferenceSource.AthleteSet:
          return c.writeI32(2);
        case FfiReferenceSource.PreviousRecord:
          return c.writeI32(3);
        case FfiReferenceSource.Typical:
          return c.writeI32(4);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

/**
 * Typealias from the type name used in the UDL file to the custom type.  This
 * is needed because the UDL type name is used in function/method signatures.
 */
export type FfiFloat32Array = Float32Array;

// FfiConverter for FfiFloat32Array
const FfiConverterTypeFfiFloat32Array = (() => {
  type TsType = FfiFloat32Array;
  type FfiType = Uint8Array;
  const intermediateConverter = FfiConverterArrayBuffer;
  class FFIConverter implements FfiConverter<FfiType, TsType> {
    lift(value: FfiType): TsType {
      const intermediate = intermediateConverter.lift(value);
      return new Float32Array(intermediate);
    }
    lower(value: TsType, alloc: RustBufferAllocator): FfiType {
      const intermediate = new Uint8Array(
        value.buffer,
        value.byteOffset,
        value.byteLength,
      ).slice().buffer;
      return intermediateConverter.lower(intermediate, alloc);
    }
    readFromCursor(c: Cursor): TsType {
      const intermediate = intermediateConverter.readFromCursor(c);
      return new Float32Array(intermediate);
    }
    writeIntoCursor(value: TsType, c: Cursor): void {
      const intermediate = new Uint8Array(
        value.buffer,
        value.byteOffset,
        value.byteLength,
      ).slice().buffer;
      intermediateConverter.writeIntoCursor(intermediate, c);
    }
    allocationSize(value: TsType): number {
      const intermediate = new Uint8Array(
        value.buffer,
        value.byteOffset,
        value.byteLength,
      ).slice().buffer;
      return intermediateConverter.allocationSize(intermediate);
    }
  }

  return new FFIConverter();
})();

