/**
 * What a feed card says about a stub, an activity intervals.icu holds but
 * does not serve. The one judge for the card, beside [`state`] for the page.
 */
export enum FfiStubVerdict {
  /**
   * intervals.icu serves the activity.
   */
  NotStub = 1,
  /**
   * A stub of Garmin's import, and a key is connected to fill it.
   */
  GarminUpdatable = 2,
  /**
   * A stub of Garmin's import and no key is connected.
   */
  NoKey = 3,
  /**
   * A stub that is not Garmin's import, so there is nothing to offer.
   */
  OtherSource = 4,
}

const FfiConverterTypeFfiStubVerdict = (() => {
  type TypeName = FfiStubVerdict;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return FfiStubVerdict.NotStub;
        case 2:
          return FfiStubVerdict.GarminUpdatable;
        case 3:
          return FfiStubVerdict.NoKey;
        case 4:
          return FfiStubVerdict.OtherSource;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case FfiStubVerdict.NotStub:
          return c.writeI32(1);
        case FfiStubVerdict.GarminUpdatable:
          return c.writeI32(2);
        case FfiStubVerdict.NoKey:
          return c.writeI32(3);
        case FfiStubVerdict.OtherSource:
          return c.writeI32(4);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

/**
 * What one feed card draws, typed from the stored body.
 *
 * Built from the body rather than `activity_metrics`, which files a body
 * with no sport as a ride and keeps heart rate and power as whole numbers.
 */
export type FfiFeedCard = {
  /**
   * The row key the body is stored under. A route or a fetch names the
   * activity by this, never by the body's own `id`, which for an uploaded
   * recording is the server's id rather than the row's.
   */
  id: string;
  /**
   * The intervals.icu id a web link may name. None for a demo row and for
   * a recording no server has named.
   */
  intervalsWebId?: string;
  /**
   * The sport as the body carries it. None when it names none.
   */
  sportType?: string;
  /**
   * Empty when the body has none.
   */
  name: string;
  /**
   * The wall-clock start as the body carries it, with no zone. Empty when
   * the body has none.
   */
  startDateLocal: string;
  /**
   * Metres.
   */
  distance?: number;
  /**
   * Seconds.
   */
  movingTime?: number;
  /**
   * Metres climbed.
   */
  elevationGain?: number;
  /**
   * Beats per minute.
   */
  avgHr?: number;
  /**
   * Watts.
   */
  avgPower?: number;
  trainingLoad?: number;
  /**
   * Kilocalories.
   */
  calories?: number;
  hasWeather: boolean;
  /**
   * Degrees Celsius.
   */
  averageWeatherTemp?: number;
  /**
   * The elevation skyline as intervals.icu encodes it, base64.
   */
  skylineChartBytes?: string;
  /**
   * Whether the activity recorded a `latlng` stream.
   */
  hasGps: boolean;
  /**
   * Whether the activity recorded an `altitude` stream, which makes a zero
   * climb a measurement rather than a missing one.
   */
  hasAltitude: boolean;
  /**
   * The fault the last sync met readying this activity, which the card
   * marks with a retry. None when its last readying was clean.
   */
  syncFailure?: FfiActivitySyncFailure;
  /**
   * Whether the activity is a stub intervals.icu does not serve, and what
   * the card offers for it.
   */
  stub: FfiStubVerdict;
};

