// FfiConverter for enum FfiCatalogueEmptyReason
const FfiConverterTypeFfiCatalogueEmptyReason = (() => {
  type TypeName = FfiCatalogueEmptyReason;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return new FfiCatalogueEmptyReason.NoGpsActivities();
        case 2:
          return new FfiCatalogueEmptyReason.NotYetRun({
            awaiting: FfiConverterUInt32.readFromCursor(c),
          });
        case 3:
          return new FfiCatalogueEmptyReason.Running({
            phase: FfiConverterString.readFromCursor(c),
            percent: FfiConverterUInt32.readFromCursor(c),
          });
        case 4:
          return new FfiCatalogueEmptyReason.Held({
            hold: FfiConverterTypeFfiDetectionHold.readFromCursor(c),
          });
        case 5:
          return new FfiCatalogueEmptyReason.NoneFound({
            minActivities: FfiConverterUInt32.readFromCursor(c),
          });
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value.tag) {
        case FfiCatalogueEmptyReason_Tags.NoGpsActivities: {
          c.writeI32(1);
          return;
        }
        case FfiCatalogueEmptyReason_Tags.NotYetRun: {
          c.writeI32(2);
          const inner = value.inner;
          FfiConverterUInt32.writeIntoCursor(inner.awaiting, c);
          return;
        }
        case FfiCatalogueEmptyReason_Tags.Running: {
          c.writeI32(3);
          const inner = value.inner;
          FfiConverterString.writeIntoCursor(inner.phase, c);
          FfiConverterUInt32.writeIntoCursor(inner.percent, c);
          return;
        }
        case FfiCatalogueEmptyReason_Tags.Held: {
          c.writeI32(4);
          const inner = value.inner;
          FfiConverterTypeFfiDetectionHold.writeIntoCursor(inner.hold, c);
          return;
        }
        case FfiCatalogueEmptyReason_Tags.NoneFound: {
          c.writeI32(5);
          const inner = value.inner;
          FfiConverterUInt32.writeIntoCursor(inner.minActivities, c);
          return;
        }
        default:
          // Throwing from here means that FfiCatalogueEmptyReason_Tags hasn't matched an ordinal.
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    allocationSize(value: TypeName): number {
      switch (value.tag) {
        case FfiCatalogueEmptyReason_Tags.NoGpsActivities: {
          return 4;
        }
        case FfiCatalogueEmptyReason_Tags.NotYetRun: {
          const inner = value.inner;
          let size = 4;
          size += FfiConverterUInt32.allocationSize(inner.awaiting);
          return size;
        }
        case FfiCatalogueEmptyReason_Tags.Running: {
          const inner = value.inner;
          let size = 4;
          size += FfiConverterString.allocationSize(inner.phase);
          size += FfiConverterUInt32.allocationSize(inner.percent);
          return size;
        }
        case FfiCatalogueEmptyReason_Tags.Held: {
          const inner = value.inner;
          let size = 4;
          size += FfiConverterTypeFfiDetectionHold.allocationSize(inner.hold);
          return size;
        }
        case FfiCatalogueEmptyReason_Tags.NoneFound: {
          const inner = value.inner;
          let size = 4;
          size += FfiConverterUInt32.allocationSize(inner.minActivities);
          return size;
        }
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
  }
  return new FFIConverter();
})();

/**
 * All data needed by the Routes screen in a single FFI call.
 * Supports pagination via limit/offset for groups and sections.
 */
export type FfiRoutesScreenData = {
  activityCount: number;
  groupCount: number;
  sectionCount: number;
  oldestDate?: number;
  newestDate?: number;
  groups: Array<FfiGroupWithPolyline>;
  sections: Array<FfiSectionWithPolyline>;
  /**
   * Whether more groups are available beyond the current page
   */
  hasMoreGroups: boolean;
  /**
   * Whether more sections are available beyond the current page
   */
  hasMoreSections: boolean;
  /**
   * Whether route groups need recomputation (stale after activity removal)
   */
  groupsDirty: boolean;
  /**
   * How many groups the search and the minimum activity count leave. This is
   * what the page is taken out of, and what `has_more_groups` is measured
   * against. `group_count` stays the whole catalogue.
   */
  filteredGroupCount: number;
  /**
   * How many sections the search and the hidden filters leave.
   */
  filteredSectionCount: number;
  /**
   * Auto sections the athlete has not accepted, over the whole catalogue and
   * not the page, because this is the "N to review" figure.
   */
  unacceptedAutoCount: number;
  /**
   * Auto sections the athlete has accepted, over the whole catalogue.
   */
  acceptedAutoCount: number;
  /**
   * Custom sections over the whole catalogue. The chip beside it filters the
   * catalogue, so a page-sized tally would be a lower bound nothing labels.
   */
  customCount: number;
  /**
   * Auto sections the athlete disabled or a custom one superseded, over the
   * whole catalogue. Taken before `hide_disabled` runs, which is the filter
   * this figure is the count for and which hides them by default. Distinct
   * from `ledger_retired_count`: a disabled row is still in the catalogue,
   * a ledger retirement has left it.
   */
  removedCount: number;
  /**
   * Sections that left the catalogue through a fired retirement and still
   * hold a ledger, the graveyard the retired screen lists, a record
   * restore's pending states included. This is what the entry points to the
   * graveyard gate on, and it is not the `removed_count` of disabled rows.
   */
  ledgerRetiredCount: number;
  /**
   * Of those, the ones that hold an `archived` row: the cutover's, or a
   * record restore's pending state. A later detect that dissolves a section
   * leaves no archived row, so a library with no cutover reads zero here,
   * which is what the "your matching changed" card gates on.
   */
  archivedRetiredCount: number;
  /**
   * The sports the athlete has activities in, which the sport chips offer.
   */
  availableSportTypes: Array<string>;
  /**
   * Why the routes catalogue holds no route with the minimum activity
   * count, whatever the search and the sport filter. `None` while it holds
   * one, so an empty page under a search is a search that matched nothing.
   */
  groupEmptyReason?: FfiCatalogueEmptyReason;
  /**
   * Why the sections catalogue holds no section of any kind, hidden or not.
   * `None` while it holds one.
   */
  sectionEmptyReason?: FfiCatalogueEmptyReason;
};

