/**
 * The lifecycle state TypeScript renders.
 *
 * Crosses as an enum: the word was stringified here and spelt again in a
 * TypeScript mirror, and every reader only ever branches on it. Wire order
 * is declaration order, so append and never reorder.
 */
export enum SyncState {
  Idle = 1,
  Syncing = 2,
  Paused = 3,
  AuthExpired = 4,
}

const FfiConverterTypeSyncState = (() => {
  type TypeName = SyncState;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return SyncState.Idle;
        case 2:
          return SyncState.Syncing;
        case 3:
          return SyncState.Paused;
        case 4:
          return SyncState.AuthExpired;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case SyncState.Idle:
          return c.writeI32(1);
        case SyncState.Syncing:
          return c.writeI32(2);
        case SyncState.Paused:
          return c.writeI32(3);
        case SyncState.AuthExpired:
          return c.writeI32(4);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

/**
 * Which endpoint a running sync is on, so the line an athlete reads names the
 * work rather than a counter.
 *
 * The step is the engine's to report. `completed` counts steps that landed,
 * so a label derived from it in TypeScript lags by one for every step that
 * failed, and goes wrong outright the first time the order moves.
 *
 * The wire carries the variant's position, so the order here is the contract:
 * append, never reorder. The discriminants start at one so no member is falsy.
 */
export enum FfiSyncStep {
  /**
   * The athlete profile: FTP, zones, the name on the settings screen.
   */
  Athlete = 1,
  /**
   * Per-sport settings, which the zone charts read. No run reports it now:
   * the athlete body carries them and the athlete step stores both. Kept
   * because the wire carries the position.
   */
  SportSettings = 2,
  /**
   * The wellness rows: the trailing fortnight once a year is stored, back
   * to the oldest day still owed otherwise.
   */
  Wellness = 3,
  /**
   * What the account holds against what is stored, which the window step
   * reads to know what is still owed.
   */
  Census = 4,
  /**
   * The newest owed window, the step a first launch waits on: the standby
   * lifts the moment its rows land.
   */
  Activities = 5,
  /**
   * The power and pace curves every fitness range charts.
   */
  Curves = 6,
  /**
   * Interval and lap bodies for the activities that have none.
   */
  IntervalBodies = 7,
  /**
   * The rest of the library, behind the profile slice. Its own step because
   * it is the backfill rather than the thing the standby is waiting on.
   */
  RemainingActivities = 8,
  /**
   * The newest few activities by count, ahead of every window. The step a
   * first launch actually waits on, since the window behind it spans the
   * whole library.
   */
  FirstActivities = 9,
  /**
   * The older activities a restored backup names, fetched by id so its
   * pins, cuts and history can land without waiting for the window.
   */
  RecordActivities = 10,
  /**
   * Planned workouts and notes in the forward calendar window.
   */
  Calendar = 11,
}

const FfiConverterTypeFfiSyncStep = (() => {
  type TypeName = FfiSyncStep;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return FfiSyncStep.Athlete;
        case 2:
          return FfiSyncStep.SportSettings;
        case 3:
          return FfiSyncStep.Wellness;
        case 4:
          return FfiSyncStep.Census;
        case 5:
          return FfiSyncStep.Activities;
        case 6:
          return FfiSyncStep.Curves;
        case 7:
          return FfiSyncStep.IntervalBodies;
        case 8:
          return FfiSyncStep.RemainingActivities;
        case 9:
          return FfiSyncStep.FirstActivities;
        case 10:
          return FfiSyncStep.RecordActivities;
        case 11:
          return FfiSyncStep.Calendar;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case FfiSyncStep.Athlete:
          return c.writeI32(1);
        case FfiSyncStep.SportSettings:
          return c.writeI32(2);
        case FfiSyncStep.Wellness:
          return c.writeI32(3);
        case FfiSyncStep.Census:
          return c.writeI32(4);
        case FfiSyncStep.Activities:
          return c.writeI32(5);
        case FfiSyncStep.Curves:
          return c.writeI32(6);
        case FfiSyncStep.IntervalBodies:
          return c.writeI32(7);
        case FfiSyncStep.RemainingActivities:
          return c.writeI32(8);
        case FfiSyncStep.FirstActivities:
          return c.writeI32(9);
        case FfiSyncStep.RecordActivities:
          return c.writeI32(10);
        case FfiSyncStep.Calendar:
          return c.writeI32(11);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

/**
 * Why the last sync failed, as the kind the banner branches on.
 *
 * The message beside it stays, because it carries the detail a bug report
 * needs, but it is never the thing an athlete reads. A locale table keyed on
 * the message would break the first time one is reworded, so the classifying
 * happens here, where the engine already knows which case it is in.
 *
 * The wire carries the variant's position, so the order here is the contract:
 * append, never reorder. The discriminants start at one so no member is falsy.
 */
export enum FfiSyncErrorReason {
  /**
   * The credential was refused, 401.
   */
  Unauthorized = 1,
  /**
   * The server asked for a pause, 429, and the retries ran out.
   */
  RateLimited = 2,
  /**
   * The server answered, and with something the sync could not use: a
   * non-success status, or a body that did not deserialise.
   */
  Server = 3,
  /**
   * The server was never reached. A dead radio, a captive portal, a timeout.
   */
  Network = 4,
  /**
   * A file on the device could not be read. Not a network failure.
   */
  Storage = 5,
  /**
   * There is nothing to sync with: no credential is stored, or the base URL
   * will not build a transport.
   */
  NotConfigured = 6,
  /**
   * The sync stopped in a way it has no case for, including a panic.
   */
  Internal = 7,
  /**
   * The engine went away while the run was going: a restore, or clear and
   * sync. Whatever the run had fetched had nowhere to land, so the run is
   * a failure however many steps had already succeeded.
   */
  EngineClosed = 8,
  /**
   * The device ran out of space while the sync was writing what it had
   * fetched: SQLite reported the disk full, or a write failed with no
   * space left. Freeing space is the fix, not a retry.
   */
  StorageFull = 9,
}

const FfiConverterTypeFfiSyncErrorReason = (() => {
  type TypeName = FfiSyncErrorReason;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return FfiSyncErrorReason.Unauthorized;
        case 2:
          return FfiSyncErrorReason.RateLimited;
        case 3:
          return FfiSyncErrorReason.Server;
        case 4:
          return FfiSyncErrorReason.Network;
        case 5:
          return FfiSyncErrorReason.Storage;
        case 6:
          return FfiSyncErrorReason.NotConfigured;
        case 7:
          return FfiSyncErrorReason.Internal;
        case 8:
          return FfiSyncErrorReason.EngineClosed;
        case 9:
          return FfiSyncErrorReason.StorageFull;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case FfiSyncErrorReason.Unauthorized:
          return c.writeI32(1);
        case FfiSyncErrorReason.RateLimited:
          return c.writeI32(2);
        case FfiSyncErrorReason.Server:
          return c.writeI32(3);
        case FfiSyncErrorReason.Network:
          return c.writeI32(4);
        case FfiSyncErrorReason.Storage:
          return c.writeI32(5);
        case FfiSyncErrorReason.NotConfigured:
          return c.writeI32(6);
        case FfiSyncErrorReason.Internal:
          return c.writeI32(7);
        case FfiSyncErrorReason.EngineClosed:
          return c.writeI32(8);
        case FfiSyncErrorReason.StorageFull:
          return c.writeI32(9);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

/**
 * Which piece of the track work is running.
 *
 * The wire carries the variant's position, so the order here is the contract:
 * append, never reorder. The discriminants start at one so no member is falsy.
 */
export enum FfiTrackStep {
  /**
   * The GPS pass is downloading tracks.
   */
  Downloading = 1,
  /**
   * Section detection is reading the stored tracks.
   */
  Analysing = 2,
  /**
   * The heatmap tile pass is drawing them.
   */
  DrawingHeatmap = 3,
  /**
   * The GPS pass owes tracks the request budget, or a cooldown intervals.icu
   * asked for, held back. The engine starts it again at `resumes_at_ms`.
   */
  Held = 4,
}

const FfiConverterTypeFfiTrackStep = (() => {
  type TypeName = FfiTrackStep;
  class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
    readFromCursor(c: Cursor): TypeName {
      switch (c.readI32()) {
        case 1:
          return FfiTrackStep.Downloading;
        case 2:
          return FfiTrackStep.Analysing;
        case 3:
          return FfiTrackStep.DrawingHeatmap;
        case 4:
          return FfiTrackStep.Held;
        default:
          throw new UniffiInternalError.UnexpectedEnumCase();
      }
    }
    writeIntoCursor(value: TypeName, c: Cursor): void {
      switch (value) {
        case FfiTrackStep.Downloading:
          return c.writeI32(1);
        case FfiTrackStep.Analysing:
          return c.writeI32(2);
        case FfiTrackStep.DrawingHeatmap:
          return c.writeI32(3);
        case FfiTrackStep.Held:
          return c.writeI32(4);
      }
    }
    allocationSize(value: TypeName): number {
      return 4;
    }
  }
  return new FFIConverter();
})();

/**
 * The running piece of the track work and how far it has got.
 */
export type FfiTrackStage = {
  step: FfiTrackStep;
  /**
   * Items the step has handled, of `total`: tracks for the download, tiles
   * for the heatmap, the current phase's items for detection.
   */
  completed: number;
  /**
   * Zero while the step has not counted its work yet.
   */
  total: number;
  /**
   * The step's own progress, 0 to 100. Detection weights its phases, so
   * this is not always `completed` of `total`.
   */
  percent: number;
  /**
   * When a held download starts again, as epoch milliseconds. `None` for
   * every other step. The counts beside it are zero: the window's own
   * coverage says how many tracks are still owed.
   */
  resumesAtMs?: number;
  /**
   * Whether intervals.icu asked for the wait, rather than this install's
   * own request budget. False for every other step.
   */
  heldByUpstream: boolean;
};

